import{z as n,x as d,o as r,c as B,q as s,j as l,D as e,d as A,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"RSA 与 OAEP","description":"","frontmatter":{"title":"RSA 与 OAEP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rsa-oaep.md","filePath":"cs/rsa-oaep.md","lastUpdated":1791063341000}'),p={name:"cs/rsa-oaep.md"};function m(h,a,P,S,c,D){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=s('<h1 id="rsa-与-oaep" tabindex="-1">RSA 与 OAEP <a class="header-anchor" href="#rsa-与-oaep" aria-label="Permalink to &quot;RSA 与 OAEP&quot;">​</a></h1><div class="epigraph"><p>RSA 函数是模幂；直接加密短消息既不确定也不抗选择密文。OAEP 用哈希做随机化填充，把 RSA 收成在随机预言机模型下可达到 CCA 目标的信封零件。</p><footer>—— Rivest, Shamir and Adleman, 1978；Bellare and Rogaway, Optimal Asymmetric Encryption Padding, EUROCRYPT 1994；PKCS #1 v2</footer></div><p>上一课<a href="/cs/birthday-attack">生日攻击</a>钉了哈希宽度。主干<a href="/cs/pubkey-envelope">公钥信封</a>与<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>已把 RSA 当封装选项。缺口是<strong>明文不能直接当模幂输入</strong>：必须填充。本课收 OAEP，不重推欧拉定理。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书 RSA \\(c=m^e\\bmod n\\) 确定、可乘性，选择密文下可被操纵。OAEP：用随机种子和哈希把 \\(m\\) 扩成类似一次一密的掩码块再模幂。TLS 1.3 已不用 RSA 密钥传输，但签名与遗留封装仍要理解填充。缺口是填充合同，不是再讲因数分解叙事。<span class="marginnote">术语翻译：OAEP（最优非对称加密填充）就是用「真随机种子加两轮哈希掩码，把消息搅成看不出结构的一团」的手段来做「同一条消息每次密文都不同、密文改一个比特就整块作废」的事——RSA 本体只负责搬这团东西。</span></p><h3 id="签名填充是另一套" tabindex="-1">签名填充是另一套 <a class="header-anchor" href="#签名填充是另一套" aria-label="Permalink to &quot;签名填充是另一套&quot;">​</a></h3><p>PSS 与 PKCS#1 v1.5 签名填充下一课攻击面才对照。加密填充与签名填充不能混用同一密钥语义而不加域分离。</p><p><span class="marginnote">Bellare–Rogaway OAEP。Fujisaki–Okamoto 等是同类「把陷门置换收成 CCA」的框架，本课只钉 OAEP。不要发明 arXiv 编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 RSA 陷门置换角色：公钥 \\((n,e)\\) 公开，私钥 \\(d\\) 解幂。OAEP 的两轮 Feistel 式掩码（用 \\(G,H\\) 哈希）。对照：哈希宽度受生日界约束，种子必须真随机。<span class="marginnote">数字实例：若种子只有 16 位随机，攻击者枚举 65536 个候选就能把密文重放出明文；真实方案里种子宽如哈希输出（如 256 位），穷举要 \\(2^{256}\\) 次——填充的随机性上限就是种子的随机性，种子弱则整套 OAEP 形同虚设。</span></p>',11)),(r(),l(o,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%22%5D%20--%3E%20OAEP%5B%22OAEP%20%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%A1%AB%E5%85%85%22%5D%0A%20%20R%5B%22%E9%9A%8F%E6%9C%BA%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20OAEP%0A%20%20OAEP%20--%3E%20POW%5B%22%E6%A8%A1%E5%B9%82%20e%22%5D%0A%20%20POW%20--%3E%20C%5B%22%E5%AF%86%E6%96%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[A("信封仍是：RSA 只封对称键，数据走 AEAD。OAEP 让封装在理想哈希下可归约到 RSA 陷门。实现必须常数时间模幂与严格的填充校验——校验失败不可区分，否则又是预言机。"),E("span",{class:"marginnote"},"常见误区：初学者容易以为「解封失败时返回不同的错误码方便排查」——每一种可分辨的失败提示都是一台免费预言机；正确做法是把所有失败统一成同一句「解封失败」，连报错耗时也要抹平。")],-1)),(r(),l(o,null,{default:e(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20C2%5B%22%E6%94%B6%E5%88%B0%E5%AF%86%E6%96%87%22%5D%20--%3E%20DEC%5B%22%E7%A7%81%E9%92%A5%20d%20%E8%A7%A3%E5%B9%82%22%5D%0A%20%20DEC%20--%3E%20UNMASK%5B%22%E5%8F%8D%E5%90%91%E6%8B%86%E4%B8%A4%E8%BD%AE%E6%8E%A9%E7%A0%81%20H%20%E4%B8%8E%20G%22%5D%0A%20%20UNMASK%20--%3E%20CHK%7B%22%E7%A7%8D%E5%AD%90%E4%B8%8E%E6%8E%A9%E7%A0%81%E8%87%AA%E6%B4%BD%EF%BC%9F%22%7D%0A%20%20CHK%20--%20%22%E6%98%AF%22%20--%3E%20OUT%5B%22%E4%BA%A4%E5%87%BA%E8%A2%AB%E5%B0%81%E8%A3%85%E7%9A%84%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%22%5D%0A%20%20CHK%20--%20%22%E5%90%A6%22%20--%3E%20FAIL%5B%22%E7%BB%9F%E4%B8%80%E6%8A%A5%20%E8%A7%A3%E5%B0%81%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20FAIL%20--%3E%20ND%5B%22%E9%94%99%E8%AF%AF%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%EF%BC%9A%E5%A0%B5%E6%AD%BB%E9%A2%84%E8%A8%80%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给选择密文操纵的步骤。下一课 RSA 攻击面：填充实现、共模、广播、小指数，全部当失败模式与防御，不当配方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生日界约束填充里的哈希；RSA 要随机化填充。</li><li>OAEP 把陷门置换收成 CCA 向的封装。</li><li>TLS 1.3 不用 RSA 传输密钥；遗留与签名仍要填充。</li><li>下一课：填充与数论误用的攻击面清单。</li><li>出处：Rivest, Shamir and Adleman, 1978；Bellare and Rogaway, 1994；PKCS #1。</li></ul>',4))])}const R=n(p,[["render",m]]);export{u as __pageData,R as default};
